export interface Post {
  slug: string;
  title: string;
  date: Date;
  tags: string[];
  draft: boolean;
  content: string;
  html: string;
  layout: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
  postsPerPage: number;
  includeDrafts: boolean;
  port: number;
}

export interface TemplateContext {
  site: {
    title: string;
    url: string;
  };
  page: {
    title: string;
    date?: string;
    tags?: string[];
    content?: string;
  };
  posts?: Post[];
  tags?: Array<{ name: string; count: number }>;
}

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, basename } from 'node:path';
import matter from 'gray-matter';
import { Post } from './types';
import { getMarked } from './highlight';

function slugify(name: string): string {
  return basename(name, '.md')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function walkDir(dir: string, files: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      walkDir(full, files);
    } else if (entry.endsWith('.md')) {
      files.push(full);
    }
  }
  return files;
}

export function parseFile(filePath: string, sourceDir: string): Post {
  const raw = readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);
  const html = getMarked().parse(content) as string;
  const rel = relative(sourceDir, filePath);

  return {
    slug: slugify(rel),
    title: data.title || slugify(rel),
    date: data.date ? new Date(data.date) : new Date(),
    tags: Array.isArray(data.tags) ? data.tags : [],
    draft: data.draft === true,
    content,
    html,
    layout: data.layout || 'default',
  };
}

export function parseDirectory(sourceDir: string): Post[] {
  const files = walkDir(sourceDir);
  return files.map((f) => parseFile(f, sourceDir));
}

import { Marked } from 'marked';
import hljs from 'highlight.js';

let instance: Marked | null = null;

export function getMarked(): Marked {
  if (!instance) {
    instance = new Marked();
    instance.setOptions({
      highlight: (code: string, lang: string): string => {
        if (lang && hljs.getLanguage(lang)) {
          try {
            return hljs.highlight(code, { language: lang }).value;
          } catch {
            // fall through
          }
        }
        return code;
      },
    });
  }
  return instance;
}

import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join, extname } from 'node:path';
import Handlebars from 'handlebars';
import { Post, SiteConfig, TemplateContext } from './types';

function safeName(path: string): string {
  return path.replace(/[^a-zA-Z0-9_-]/g, '_');
}

export class Renderer {
  private layouts = new Map<string, Handlebars.TemplateDelegate>();
  private partials = new Map<string, Handlebars.TemplateDelegate>();
  private templates = new Map<string, Handlebars.TemplateDelegate>();
  private templateDir: string;

  constructor(templateDir: string) {
    this.templateDir = templateDir;
    this.loadPartials(join(templateDir, 'partials'));
    this.loadLayouts(join(templateDir, 'layouts'));
  }

  private loadPartials(dir: string): void {
    if (!existsSync(dir)) return;
    for (const file of readdirSync(dir)) {
      if (!file.endsWith('.hbs') && !file.endsWith('.html')) continue;
      const name = safeName(file.replace(extname(file), ''));
      const src = readFileSync(join(dir, file), 'utf-8');
      const tpl = Handlebars.compile(src);
      this.partials.set(name, tpl);
      Handlebars.registerPartial(name, tpl);
    }
  }

  private loadLayouts(dir: string): void {
    if (!existsSync(dir)) return;
    for (const file of readdirSync(dir)) {
      if (!file.endsWith('.hbs') && !file.endsWith('.html')) continue;
      const name = safeName(file.replace(extname(file), ''));
      const src = readFileSync(join(dir, file), 'utf-8');
      const tpl = Handlebars.compile(src);
      this.layouts.set(name, tpl);
    }
  }

  loadTemplate(name: string): Handlebars.TemplateDelegate {
    if (this.templates.has(name)) return this.templates.get(name)!;
    const path = join(this.templateDir, `${name}.hbs`);
    const altPath = join(this.templateDir, `${name}.html`);
    const srcPath = existsSync(path) ? path : altPath;
    if (!existsSync(srcPath)) {
      throw new Error(`Template not found: ${name}`);
    }
    const src = readFileSync(srcPath, 'utf-8');
    const tpl = Handlebars.compile(src);
    this.templates.set(name, tpl);
    return tpl;
  }

  render(templateName: string, context: Record<string, unknown>): string {
    const tpl = this.loadTemplate(templateName);
    return tpl(context);
  }

  renderWithLayout(
    templateName: string,
    layoutName: string,
    context: Record<string, unknown>,
  ): string {
    const body = this.render(templateName, context);
    const layout = this.layouts.get(layoutName);
    if (!layout) {
      throw new Error(`Layout not found: ${layoutName}`);
    }
    return layout({ ...context, body });
  }

  renderPost(post: Post, config: SiteConfig): string {
    const ctx: TemplateContext = {
      site: { title: config.siteTitle, url: config.siteUrl },
      page: {
        title: post.title,
        date: post.date.toISOString(),
        tags: post.tags,
        content: post.html,
      },
    };
    return this.renderWithLayout('post', post.layout, ctx);
  }

  renderIndex(posts: Post[], config: SiteConfig): string {
    const tagCounts = new Map<string, number>();
    for (const p of posts) {
      for (const t of p.tags) {
        tagCounts.set(t, (tagCounts.get(t) || 0) + 1);
      }
    }
    const tags = Array.from(tagCounts.entries()).map(([name, count]) => ({
      name,
      count,
    }));

    const ctx: TemplateContext = {
      site: { title: config.siteTitle, url: config.siteUrl },
      page: { title: config.siteTitle },
      posts,
      tags,
    };
    return this.renderWithLayout('index', 'default', ctx);
  }

  renderTagPage(
    tag: string,
    posts: Post[],
    config: SiteConfig,
  ): string {
    const ctx: TemplateContext = {
      site: { title: config.siteTitle, url: config.siteUrl },
      page: { title: `Tag: ${tag}` },
      posts,
    };
    return this.renderWithLayout('tag', 'default', ctx);
  }
}

import { writeFileSync } from 'node:fs';
import { Post, SiteConfig } from './types';

export function generateRSS(posts: Post[], config: SiteConfig): string {
  const items = posts.slice(0, 20).map((p) => {
    const url = `${config.siteUrl}/${p.slug}/`;
    return `<item>
      <title><![CDATA[${p.title}]]></title>
      <link>${url}</link>
      <guid isPermaLink="true">${url}</guid>
      <pubDate>${p.date.toUTCString()}</pubDate>
      <description><![CDATA[${p.html.slice(0, 500)}]]></description>
    </item>`;
  });

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${config.siteTitle}</title>
    <link>${config.siteUrl}</link>
    <description>${config.siteTitle} RSS Feed</description>
    <atom:link href="${config.siteUrl}/feed.xml" rel="self" type="application/rss+xml"/>
    ${items.join('\n    ')}
  </channel>
</rss>`;
}

export function writeRSS(posts: Post[], config: SiteConfig): void {
  const xml = generateRSS(posts, config);
  writeFileSync(`${config.outputDir}/feed.xml`, xml, 'utf-8');
}

import { mkdirSync, writeFileSync, cpSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { Post, SiteConfig } from './types';
import { parseDirectory } from './parser';
import { Renderer } from './renderer';
import { writeRSS } from './rss';

function ensureDir(dir: string): void {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

function getLiveReloadScript(port: number): string {
  return `<script>
(function(){var w=new WebSocket('ws://localhost:${port}/__livereload');w.onmessage=function(e){if(e.data==='reload')location.reload();};})();
</script>`;
}

export function generate(config: SiteConfig, injectLiveReload = false): void {
  ensureDir(config.outputDir);

  let posts = parseDirectory(config.sourceDir);
  if (!config.includeDrafts) {
    posts = posts.filter((p) => !p.draft);
  }
  posts.sort((a, b) => b.date.getTime() - a.date.getTime());

  const renderer = new Renderer(config.templateDir);
  const reloadSnippet = injectLiveReload ? getLiveReloadScript(config.port) : '';

  for (const post of posts) {
    const html = renderer.renderPost(post, config) + reloadSnippet;
    const outDir = join(config.outputDir, post.slug);
    ensureDir(outDir);
    writeFileSync(join(outDir, 'index.html'), html, 'utf-8');
  }

  const tagMap = new Map<string, Post[]>();
  for (const post of posts) {
    for (const tag of post.tags) {
      if (!tagMap.has(tag)) tagMap.set(tag, []);
      tagMap.get(tag)!.push(post);
    }
  }

  for (const [tag, tagPosts] of tagMap) {
    const tagSlug = tag.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    const html =
      renderer.renderTagPage(tag, tagPosts, config) + reloadSnippet;
    const outDir = join(config.outputDir, 'tags', tagSlug);
    ensureDir(outDir);
    writeFileSync(join(outDir, 'index.html'), html, 'utf-8');
  }

  const indexHtml = renderer.renderIndex(posts, config) + reloadSnippet;
  ensureDir(config.outputDir);
  writeFileSync(join(config.outputDir, 'index.html'), indexHtml, 'utf-8');

  writeRSS(posts, config);

  const assetsDir = join(config.templateDir, 'assets');
  if (existsSync(assetsDir)) {
    cpSync(assetsDir, join(config.outputDir, 'assets'), {
      recursive: true,
    });
  }
}

import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { readFileSync, existsSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { SiteConfig } from './types';
import { generate } from './generator';

const MIME: Record<string, string> = {
  '.html': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.xml': 'application/xml',
};

function serveFile(res: ServerResponse, path: string): void {
  try {
    const data = readFileSync(path);
    const ext = extname(path);
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'text/plain' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('Not Found');
  }
}

export function startServer(config: SiteConfig): void {
  const wss = new WebSocketServer({ port: config.port + 1 });
  const clients = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => clients.delete(ws));
  });

  function notifyClients(): void {
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const url = req.url || '/';
    let filePath = join(config.outputDir, url === '/' ? 'index.html' : url);

    if (!existsSync(filePath)) {
      filePath = join(config.outputDir, url, 'index.html');
    }
    if (!existsSync(filePath)) {
      filePath = join(config.outputDir, 'index.html');
    }

    serveFile(res, filePath);
  });

  const debounceTimer: ReturnType<typeof setTimeout> | null = null;
  function scheduleRebuild(): void {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      try {
        generate(config, true);
        notifyClients();
        console.log('[staticsite] rebuilt');
      } catch (err) {
        console.error('[staticsite] build error:', err);
      }
    }, 200);
  }

  const watcher = chokidar.watch(
    [config.sourceDir, config.templateDir],
    { ignoreInitial: true },
  );
  watcher.on('all', scheduleRebuild);

  server.listen(config.port, () => {
    generate(config, true);
    console.log(`[staticsite] dev server at http://localhost:${config.port}`);
  });

  process.on('SIGINT', () => {
    watcher.close();
    wss.close();
    server.close();
    process.exit(0);
  });
}

#!/usr/bin/env node
import { Command } from 'commander';
import { SiteConfig } from './types';
import { generate } from './generator';
import { startServer } from './server';

const program = new Command();

program
  .name('staticsite')
  .description('Static site generator from Markdown with YAML frontmatter')
  .version('1.0.0');

program
  .command('build')
  .description('Build the static site')
  .requiredOption('-s, --source <dir>', 'Source directory of Markdown files', 'content')
  .requiredOption('-t, --templates <dir>', 'Template directory', 'templates')
  .requiredOption('-o, --output <dir>', 'Output directory', 'public')
  .option('--title <title>', 'Site title', 'My Site')
  .option('--url <url>', 'Site URL', 'http://localhost:3000')
  .option('--drafts', 'Include draft posts', false)
  .option('--posts-per-page <n>', 'Posts per page', '10')
  .action((opts) => {
    const config: SiteConfig = {
      sourceDir: opts.source,
      templateDir: opts.templates,
      outputDir: opts.output,
      siteTitle: opts.title,
      siteUrl: opts.url,
      includeDrafts: opts.drafts,
      postsPerPage: parseInt(opts.postsPerPage, 10),
      port: 3000,
    };
    generate(config);
    console.log(`[staticsite] site built to ${config.outputDir}`);
  });

program
  .command('serve')
  .description('Start dev server with live reload')
  .requiredOption('-s, --source <dir>', 'Source directory of Markdown files', 'content')
  .requiredOption('-t, --templates <dir>', 'Template directory', 'templates')
  .requiredOption('-o, --output <dir>', 'Output directory', 'public')
  .option('--title <title>', 'Site title', 'My Site')
  .option('--url <url>', 'Site URL', 'http://localhost:3000')
  .option('--drafts', 'Include draft posts', false)
  .option('-p, --port <port>', 'Dev server port', '3000')
  .option('--posts-per-page <n>', 'Posts per page', '10')
  .action((opts) => {
    const config: SiteConfig = {
      sourceDir: opts.source,
      templateDir: opts.templates,
      outputDir: opts.output,
      siteTitle: opts.title,
      siteUrl: `http://localhost:${opts.port}`,
      includeDrafts: opts.drafts,
      postsPerPage: parseInt(opts.postsPerPage, 10),
      port: parseInt(opts.port, 10),
    };
    startServer(config);
  });

program.parse();

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['test/**/*.test.ts'],
    environment: 'node',
  },
});

import { describe, it, expect } from 'vitest';
import { parseFile, parseDirectory } from '../src/parser';
import { join } from 'node:path';

const FIXTURES = join(__dirname, 'fixtures', 'content');

describe('parseFile', () => {
  it('parses frontmatter title from YAML', () => {
    const post = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(post.title).toBe('Hello World');
  });

  it('parses date from frontmatter', () => {
    const post = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(post.date).toBeInstanceOf(Date);
    expect(post.date.toISOString().slice(0, 10)).toBe('2024-01-15');
  });

  it('parses tags from frontmatter', () => {
    const post = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(post.tags).toEqual(['typescript', 'web']);
  });

  it('detects draft posts', () => {
    const draft = parseFile(join(FIXTURES, 'draft-post.md'), FIXTURES);
    expect(draft.draft).toBe(true);

    const published = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(published.draft).toBe(false);
  });

  it('parses layout from frontmatter', () => {
    const post = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(post.layout).toBe('post');
  });

  it('defaults layout to "default" when not specified', () => {
    const post = parseFile(join(FIXTURES, 'nested', 'another-post.md'), FIXTURES);
    expect(post.layout).toBe('default');
  });

  it('converts markdown content to HTML', () => {
    const post = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(post.html).toContain('<h1>Hello World</h1>');
    expect(post.html).toContain('<strong>bold</strong>');
  });

  it('generates a slug from file path', () => {
    const post = parseFile(join(FIXTURES, 'hello-world.md'), FIXTURES);
    expect(post.slug).toBe('hello-world');
  });

  it('handles nested directories for slug generation', () => {
    const post = parseFile(
      join(FIXTURES, 'nested', 'another-post.md'),
      FIXTURES,
    );
    expect(post.slug).toBe('nested-another-post');
  });

  it('uses default title from slug when frontmatter title is missing', () => {
    // File with no title in frontmatter
    const raw = join(FIXTURES, 'nested', 'another-post.md');
    // another-post.md has a title, so let's test the default date behavior instead
    const post = parseFile(raw, FIXTURES);
    expect(post.date).toBeInstanceOf(Date);
  });
});

describe('parseDirectory', () => {
  it('parses all markdown files in directory recursively', () => {
    const posts = parseDirectory(FIXTURES);
    expect(posts.length).toBe(3);
  });

  it('includes draft posts in raw parse results', () => {
    const posts = parseDirectory(FIXTURES);
    const drafts = posts.filter((p) => p.draft);
    expect(drafts.length).toBe(1);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { join } from 'node:path';
import { mkdirSync, writeFileSync, rmSync, existsSync } from 'node:fs';
import { Renderer } from '../src/renderer';
import { Post, SiteConfig } from '../src/types';

const TEMPLATE_DIR = join(__dirname, 'fixtures', 'templates');

function makeConfig(): SiteConfig {
  return {
    sourceDir: join(__dirname, 'fixtures', 'content'),
    templateDir: TEMPLATE_DIR,
    outputDir: join(__dirname, 'fixtures', 'output'),
    siteTitle: 'Test Site',
    siteUrl: 'http://example.com',
    postsPerPage: 10,
    includeDrafts: false,
    port: 3000,
  };
}

function makePost(overrides: Partial<Post> = {}): Post {
  return {
    slug: 'test-post',
    title: 'Test Post',
    date: new Date('2024-01-01'),
    tags: ['test'],
    draft: false,
    content: 'Hello',
    html: '<p>Hello</p>',
    layout: 'default',
    ...overrides,
  };
}

describe('Renderer', () => {
  let renderer: Renderer;

  beforeEach(() => {
    renderer = new Renderer(TEMPLATE_DIR);
  });

  describe('layouts', () => {
    it('loads layouts from layouts directory', () => {
      renderer = new Renderer(TEMPLATE_DIR);
      const result = renderer.renderWithLayout(
        'post',
        'default',
        { page: { title: 'Hello' }, site: { title: 'Site', url: '' } },
      );
      expect(result).toContain('<html');
      expect(result).toContain('<h1>Hello</h1>');
    });

    it('renders body content inside layout', () => {
      const result = renderer.renderWithLayout(
        'post',
        'default',
        {
          page: { title: 'My Page', content: '<p>Body</p>' },
          site: { title: 'Site', url: '' },
        },
      );
      expect(result).toContain('<p>Body</p>');
      expect(result).toContain('My Page');
    });

    it('throws for missing layout', () => {
      expect(() =>
        renderer.renderWithLayout('post', 'nonexistent', {
          page: { title: 'X' },
          site: { title: 'S', url: '' },
        }),
      ).toThrow('Layout not found');
    });
  });

  describe('partials', () => {
    it('renders partials with {{> partialName}}', () => {
      const result = renderer.renderWithLayout(
        'post',
        'default',
        {
          page: { title: 'Test' },
          site: { title: 'Site', url: '' },
          tags: [{ name: 'js', count: 3 }],
        },
      );
      expect(result).toContain('<nav>');
      expect(result).toContain('Home');
    });
  });

  describe('renderPost', () => {
    it('renders a complete post page', () => {
      const post = makePost({
        title: 'My Article',
        html: '<p>Content here</p>',
        layout: 'post',
      });
      const result = renderer.renderPost(post, makeConfig());
      expect(result).toContain('<h1>My Article</h1>');
      expect(result).toContain('<p>Content here</p>');
      expect(result).toContain('<time>');
    });
  });

  describe('renderIndex', () => {
    it('renders index with list of posts', () => {
      const posts = [
        makePost({ title: 'Post A', slug: 'a' }),
        makePost({ title: 'Post B', slug: 'b' }),
      ];
      const result = renderer.renderIndex(posts, makeConfig());
      expect(result).toContain('Post A');
